 )]
 fn ensure_pte(
     pt: Table<PageTableEntry>,
     pte_idx: TableIndex,
     phys_addr: usize,
 ) -> Result<(), Error> {
     let pte: PageTableEntry = unsafe { pt.read(pte_idx) }.ok_or_else(|| {
         let reason: &str = "invalid PTE read from page table";
         error!("ensure_pte(): {reason}");
         Error::new(ErrorCode::InvalidArgument, reason)
     })?;

